#!/usr/bin/env node
// ADR:codeforge-doctor-command
/**
 * codeforge-doctor — 主动诊断 CodeForge 安装健康状态
 *
 * 用法：
 *   node bin/codeforge-doctor.mjs              # 默认检查 global (~/.config/opencode)
 *   node bin/codeforge-doctor.mjs --project    # 检查 project (<cwd>/.opencode)
 *   codeforge doctor                            # 经 dispatcher
 *   codeforge doctor --project                  # 检查项目级
 *
 * 说明：
 *   不依赖 dist/，直接 import install.mjs export（零依赖 ESM），
 *   npm 安装场景下也能运行。
 *
 *   检查项：
 *     D1 manifest 登记但 disk 缺失（来源2：外部腐蚀）
 *     D2 source 有但 disk 缺失（来源1/2：未安装或被删）
 *     D3 disk∩source 但 manifest 无（manifest 失配）
 *     第三方文件（disk 有但不在 manifest 也不在 source）→ 静默跳过
 *
 *   exit code：有 ✗ → 1，仅 ⚠ → 0，全绿 → 0（便于脚本化）
 *
 *   scope 提示：显式标注当前检查的是哪个 target，对治跨 mode 混淆（来源1）。
 */

import { existsSync } from "node:fs"
import * as path from "node:path"
import * as os from "node:os"
import * as url from "node:url"

const __filename = url.fileURLToPath(import.meta.url)
const __dirname = path.dirname(__filename)
const REPO_ROOT = path.resolve(__dirname, "..")

// ────────────────────────────────────────────────────────────────────
// import install.mjs export（compareManifestVsDisk / readMdManifest / MD_MANIFEST_REL）
// ────────────────────────────────────────────────────────────────────
const installMjs = path.join(REPO_ROOT, "install.mjs")
let compareManifestVsDisk, MD_MANIFEST_REL

try {
  const mod = await import(url.pathToFileURL(installMjs).href)
  compareManifestVsDisk = mod.compareManifestVsDisk
  MD_MANIFEST_REL = mod.MD_MANIFEST_REL
} catch (e) {
  console.error(`✗ 无法加载 install.mjs：${e?.message ?? e}`)
  console.error(`  请确认 install.mjs 存在于：${installMjs}`)
  process.exit(1)
}

// ────────────────────────────────────────────────────────────────────
// 颜色 / 日志
// ────────────────────────────────────────────────────────────────────
const TTY = process.stdout.isTTY
const C = TTY
  ? { reset: "\x1b[0m", bold: "\x1b[1m", red: "\x1b[31m", green: "\x1b[32m", yellow: "\x1b[33m", cyan: "\x1b[36m", dim: "\x1b[2m" }
  : { reset: "", bold: "", red: "", green: "", yellow: "", cyan: "", dim: "" }

// ────────────────────────────────────────────────────────────────────
// 路径解析（与 install.mjs resolvePaths 等价精简版）
// ────────────────────────────────────────────────────────────────────
function xdgConfigHome() {
  if (process.env.XDG_CONFIG_HOME) return process.env.XDG_CONFIG_HOME
  if (process.platform === "win32" && process.env.APPDATA) return process.env.APPDATA
  return path.join(os.homedir(), ".config")
}

function resolveTarget(args) {
  if (args.project) {
    return { mode: "project", targetRoot: path.join(process.cwd(), ".opencode") }
  }
  return { mode: "global", targetRoot: path.join(xdgConfigHome(), "opencode") }
}

// ────────────────────────────────────────────────────────────────────
// 参数解析
// ────────────────────────────────────────────────────────────────────
 function parseArgs(argv) {
   const args = { project: false, help: false, runtime: false, guard: false }
   for (const a of argv) {
     if (a === "--project" || a === "-p") args.project = true
     if (a === "--help" || a === "-h") args.help = true
     // ADR:zero-command-worktree-convergence Amendment (2026-06-12) Phase 6c —— runtime 健康度段
     if (a === "--runtime" || a === "-r") args.runtime = true
     // ADR:guard-contextual-bash-allow Phase 4 —— guard 诊断段
     if (a === "--guard" || a === "-g") args.guard = true
   }
   return args
 }

// ────────────────────────────────────────────────────────────────────
// CLI
// ────────────────────────────────────────────────────────────────────
const rawArgs = process.argv.slice(2)
const args = parseArgs(rawArgs)

if (args.help) {
  console.log(`${C.bold}codeforge doctor${C.reset} — 诊断 CodeForge 安装健康状态

用法：
  codeforge doctor             # 检查 global (~/.config/opencode)
  codeforge doctor --project   # 检查 project (<cwd>/.opencode)
  codeforge doctor --runtime   # 额外检查当前项目的 worktree 运行时健康度
  codeforge doctor --guard     # guard 诊断（激活状态 / mainRoot / 白名单 / env + 解析态 / 指引）

检查项：
  D1  manifest 登记但 disk 缺失 → ✗（建议跑 codeforge install）
  D2  source 有但 disk 缺失     → ✗（建议跑 codeforge install）
  D3  disk∩source 但 manifest 无 → ⚠（manifest 可能未更新）
  第三方 .md 文件（不在 manifest 也不在 source）→ 静默跳过
  --runtime  worktree 健康度（追踪文件 / 超期 worktree / 待审 / 留痕 等 8 类信号，带下一步提示）
  --guard    guard 诊断（激活状态 / mainRoot / 白名单 / env + 解析态 / 指引）

exit code：有 ✗ → 1，仅 ⚠ → 0，全绿 → 0`)
  process.exit(0)
}

const { mode, targetRoot } = resolveTarget(args)
const shortenHome = (p) => {
  const home = os.homedir()
  return home && p.startsWith(home) ? "~" + p.slice(home.length) : p
}

console.log(`${C.bold}codeforge doctor${C.reset}`)
console.log(`  scope  : ${C.cyan}${mode}${C.reset}`)
console.log(`  target : ${shortenHome(targetRoot)}`)
if (!existsSync(targetRoot)) {
  console.log(`  ${C.yellow}⚠${C.reset}  target 目录不存在（未安装？）`)
  console.log(`  建议：跑 ${C.bold}codeforge install${C.reset} 安装 CodeForge`)
  process.exit(0)
}
console.log()

// 检查 manifest 是否存在（仅提示，不阻断后续检查）
const manifestPath = path.join(targetRoot, MD_MANIFEST_REL)
if (!existsSync(manifestPath)) {
  console.log(`  ${C.yellow}⚠${C.reset}  manifest 文件不存在：${shortenHome(manifestPath)}`)
  console.log(`  提示：可能是首次安装前、或 manifest 被删除。建议跑 ${C.bold}codeforge install${C.reset}`)
  console.log()
}

// 执行三方比对
let result
try {
  result = compareManifestVsDisk({ targetRoot, sourceRoot: REPO_ROOT })
} catch (e) {
  console.error(`${C.red}✗${C.reset} compareManifestVsDisk 执行失败：${e?.message ?? e}`)
  process.exit(1)
}

const { missing, unmanaged, stale } = result
let hasErrors = false

// D1：manifest 登记但 disk 缺失
if (missing.length > 0) {
  hasErrors = true
  console.log(`${C.red}✗${C.reset} ${C.bold}D1 manifest 登记但 disk 缺失${C.reset}（${missing.length} 个文件）：`)
  for (const { dir, file } of missing) {
    console.log(`  ${C.red}✗${C.reset}  ${dir}/${file}`)
  }
  console.log(`  建议：跑 ${C.bold}codeforge install${C.reset} 重新安装缺失文件`)
  console.log()
}

// D2：source 有但 disk 缺失
if (unmanaged.length > 0) {
  hasErrors = true
  console.log(`${C.red}✗${C.reset} ${C.bold}D2 source 有但 disk 缺失${C.reset}（${unmanaged.length} 个文件，可能未安装）：`)
  for (const { dir, file } of unmanaged) {
    console.log(`  ${C.red}✗${C.reset}  ${dir}/${file}`)
  }
  console.log(`  建议：跑 ${C.bold}codeforge install${C.reset} 安装缺失文件`)
  console.log()
}

// D3：disk∩source 但 manifest 无
if (stale.length > 0) {
  console.log(`${C.yellow}⚠${C.reset}  ${C.bold}D3 disk∩source 但 manifest 未登记${C.reset}（${stale.length} 个文件，manifest 可能未更新）：`)
  for (const { dir, file } of stale) {
    console.log(`  ${C.yellow}⚠${C.reset}  ${dir}/${file}`)
  }
  console.log(`  建议：跑 ${C.bold}codeforge install${C.reset} 刷新 manifest`)
  console.log()
}

// 全绿
if (!hasErrors && stale.length === 0) {
  console.log(`${C.green}✓${C.reset} 所有文件检查通过，CodeForge 安装健康`)
  if (mode === "global") {
    console.log(`  ${C.dim}提示：若你在项目目录里跑过 node install.mjs，也可跑 codeforge doctor --project 检查项目级${C.reset}`)
  }
}

// ────────────────────────────────────────────────────────────────────
// --runtime：worktree 运行时健康度（ADR:zero-command-worktree-convergence Phase 6c）
//
// 经 dist bundle 动态 import collectHealthDigest（dist 不存在 = 未 build → 优雅降级提示，
// 不阻断既有安装检查结果）。健康度查询只读，绝不 mutate。
// ────────────────────────────────────────────────────────────────────
if (args.runtime) {
  console.log()
  console.log(`${C.bold}runtime 健康度${C.reset}（当前项目 worktree）`)
  const distIndex = path.join(REPO_ROOT, "dist", "index.js")
  if (!existsSync(distIndex)) {
    console.log(`  ${C.yellow}⚠${C.reset}  dist 未构建（${shortenHome(distIndex)} 不存在），跳过 runtime 检查`)
    console.log(`  建议：跑 ${C.bold}npm run build${C.reset} 后重试`)
  } else {
    try {
      const { collectHealthDigest } = await import(url.pathToFileURL(distIndex).href)
      if (typeof collectHealthDigest !== "function") {
        console.log(`  ${C.yellow}⚠${C.reset}  当前 dist 版本不含 collectHealthDigest（旧版本？），请重新 build`)
      } else {
        const digest = await collectHealthDigest(process.cwd())
        if (!digest || !digest.hasIssues) {
          console.log(`  ${C.green}✓${C.reset} worktree 运行时健康，无需操作`)
        } else {
          for (const sig of digest.signals) {
            const icon = sig.informational ? `${C.dim}ℹ${C.reset}` : `${C.yellow}⚠${C.reset}`
            console.log(`  ${icon}  ${sig.nextStep}`)
          }
        }
      }
    } catch (e) {
      console.log(`  ${C.yellow}⚠${C.reset}  runtime 健康度采集失败：${e?.message ?? e}`)
      console.log(`  ${C.dim}（不影响上方安装检查结果）${C.reset}`)
    }
  }
}

// ────────────────────────────────────────────────────────────────────
// --guard：guard 诊断（ADR:guard-contextual-bash-allow Phase 4）
// 完全复刻 --runtime 的 dist 动态 import 降级模式。
// 退出码不受 --guard 影响（诊断纯展示）。
// ────────────────────────────────────────────────────────────────────
if (args.guard) {
  console.log()
  console.log(`${C.bold}guard 诊断${C.reset}（session-worktree-guard）`)
  const distIndex = path.join(REPO_ROOT, "dist", "index.js")
  if (!existsSync(distIndex)) {
    console.log(`  ${C.yellow}⚠${C.reset}  dist 未构建，跳过 guard 诊断（跑 ${C.bold}npm run build${C.reset} 后重试）`)
  } else {
    try {
      const { collectGuardDiagnostics } = await import(url.pathToFileURL(distIndex).href)
      if (typeof collectGuardDiagnostics !== "function") {
        console.log(`  ${C.yellow}⚠${C.reset}  当前 dist 不含 collectGuardDiagnostics，请重新 build`)
      } else {
        const d = await collectGuardDiagnostics(process.cwd())
        const onoff = d.activated ? `${C.green}激活${C.reset}` : `${C.dim}未激活${C.reset}`
        console.log(`  状态     : ${onoff}（原因：${d.activationReason}）`)
        console.log(`  mainRoot : ${shortenHome(d.mainRoot)}`)
        console.log(`  类B白名单: ${d.classBCallerWhitelist.join(", ") || "(空)"}`)
        // ── raw env + 解析态（ADR:guard-contextual-bash-allow Phase 4 rev2）──
        const ga = d.guardAllowParsed
        console.log(`  CODEFORGE_GUARD_ALLOW=${d.env.CODEFORGE_GUARD_ALLOW ?? "(未设)"}`)
        console.log(`    ${C.dim}→ allowAll: ${ga.allowAll}, allowBash: ${ga.allowBash}, unknown: ${ga.unknown}${C.reset}`)
        console.log(`  CODEFORGE_GUARD_LEGACY_CLASSB=${d.env.CODEFORGE_GUARD_LEGACY_CLASSB ?? "(未设)"}`)
        console.log(`    ${C.dim}→ legacyClassB: ${d.legacyClassB}${C.reset}`)
        console.log(`  CODEFORGE_DISABLE_WORKTREE_GUARD=${d.env.CODEFORGE_DISABLE_WORKTREE_GUARD ?? "(未设)"}`)
        console.log(`  CODEFORGE_FORCE_WORKTREE_GUARD=${d.env.CODEFORGE_FORCE_WORKTREE_GUARD ?? "(未设)"}`)
        console.log(`  ${C.cyan}指引${C.reset}    : ${d.hint}`)
      }
    } catch (e) {
      console.log(`  ${C.yellow}⚠${C.reset}  guard 诊断采集失败：${e?.message ?? e}`)
    }
  }
}

process.exit(hasErrors ? 1 : 0)

#!/usr/bin/env node
/**
 * codeforge-runtime-info — 打印当前项目对应的全局运行时目录
 *
 * 用法：
 *   node bin/codeforge-runtime-info.mjs              # 当前 cwd
 *   node bin/codeforge-runtime-info.mjs <project>    # 指定项目根
 *   codeforge runtime where                           # 经 dispatcher
 *   npx codeforge-runtime where                       # 经 npm bin
 *
 * 说明：与 lib/runtime-paths.ts 里的 runtimeDir / readProjectMeta 算法
 * 完全一致；这里 inline 一份精简实现，目的是让 bin 脚本无需依赖
 * dist/ 或 .ts loader，在任何安装方式下都能运行。
 *
 * 任何算法变更必须同步修改 lib/runtime-paths.ts 与本文件——见 AGENTS.md
 * "运行时数据 vs 项目配置" 章节。
 */

import { existsSync, readFileSync } from "node:fs"
import * as path from "node:path"
import * as os from "node:os"
import * as crypto from "node:crypto"

// ────────────────────────────────────────────────────────────────────
// runtimeRoot / projectKey / runtimeDir / readProjectMeta
// 与 lib/runtime-paths.ts 等价的精简实现
// ────────────────────────────────────────────────────────────────────

function runtimeRoot(env = process.env, platform = process.platform, homeDir = os.homedir()) {
  const xdg = env.XDG_DATA_HOME
  if (xdg && xdg.trim().length > 0) {
    return path.normalize(path.resolve(path.join(xdg, "codeforge")))
  }
  if (platform === "win32") {
    const localAppData = env.LOCALAPPDATA
    if (localAppData && localAppData.trim().length > 0) {
      return path.normalize(path.resolve(path.join(localAppData, "codeforge")))
    }
    return path.normalize(path.resolve(path.join(homeDir, "AppData", "Local", "codeforge")))
  }
  return path.normalize(path.resolve(path.join(homeDir, ".local", "share", "codeforge")))
}

function projectKey(absRoot) {
  const resolved = path.resolve(absRoot)
  return crypto.createHash("sha256").update(resolved).digest("hex").slice(0, 12)
}

function runtimeDir(absRoot) {
  const resolved = path.resolve(absRoot)
  const root = runtimeRoot()
  return path.normalize(path.resolve(path.join(root, "projects", projectKey(resolved))))
}

function readProjectMeta(absRoot) {
  const dir = runtimeDir(absRoot)
  const metaFile = path.join(dir, ".meta.json")
  if (!existsSync(metaFile)) return null
  try {
    const parsed = JSON.parse(readFileSync(metaFile, "utf8"))
    if (typeof parsed.absPath !== "string") return null
    return {
      absPath: parsed.absPath,
      hostname: typeof parsed.hostname === "string" ? parsed.hostname : "",
      createdAt: typeof parsed.createdAt === "string" ? parsed.createdAt : "",
    }
  } catch {
    return null
  }
}

// ────────────────────────────────────────────────────────────────────
// CLI
// ────────────────────────────────────────────────────────────────────

const args = process.argv.slice(2)

// 兼容 `codeforge runtime where <path>`：第一个非 flag 参数是子命令 where（可选）
let projectArg = null
for (const a of args) {
  if (a.startsWith("-")) continue
  if (a === "where") continue
  projectArg = a
  break
}

const root = path.resolve(projectArg ?? process.cwd())
const dir = runtimeDir(root)
const meta = readProjectMeta(root)

console.log("project:    ", root)
console.log("runtime dir:", dir)
console.log("exists:     ", existsSync(dir))
if (meta) {
  console.log("created at: ", meta.createdAt)
  console.log("first abs:  ", meta.absPath)
  if (meta.absPath !== root) {
    console.log("⚠️  abs path mismatch — possible hash collision or symlink confusion")
  }
} else {
  console.log("(no .meta.json — runtime dir 尚未被任何 CodeForge 模块创建)")
}

#!/usr/bin/env node
/**
 * codeforge — opencode 零侵入扩展包的安装入口
 * ADR:cli-deadcode-cleanup
 *
 * 一行命令安装：
 *   npm install -g @andyqiu/codeforge
 *
 * 子命令：
 *   install    [--dry-run]
 *               把 CodeForge 单 bundle 注入到 opencode（写 opencode.json plugin entry）
 *   uninstall               卸载（不动 opencode 自身）
 *   list                              探测 opencode 是否在机器上
 *   version                           打印版本
 *   runtime where [<path>]            打印当前项目对应的全局运行时目录
 *   adr-init   [--force] [--dry-run] [--write-prepare] [--no-pre-push]
 *                                     把 ADR 体系（hooks + scripts + 模板）下发到当前 git 项目
 *   help [<cmd>]                      打印帮助
 *
 * 强制全局安装（~/.config/opencode/），不再支持项目级安装。
 *
 * 只支持 opencode：CodeForge 是单 bundle plugin，跑在 opencode 1.14+ 上（持续跟主线）。
 * Cursor / Claude Code / Codex 都不能加载这种 plugin（API 不兼容），所以不假装支持。
 */

import { spawnSync } from "node:child_process"
import { existsSync, readFileSync } from "node:fs"
import * as path from "node:path"
import * as url from "node:url"

const __filename = url.fileURLToPath(import.meta.url)
const __dirname = path.dirname(__filename)
const REPO_ROOT = path.resolve(__dirname, "..")

// ────────────────────────────────────────────────────────────────────
// 颜色 / 日志
// ────────────────────────────────────────────────────────────────────
const TTY = process.stdout.isTTY
const C = TTY
  ? { reset: "\x1b[0m", bold: "\x1b[1m", red: "\x1b[31m", green: "\x1b[32m", yellow: "\x1b[33m", cyan: "\x1b[36m", dim: "\x1b[2m" }
  : { reset: "", bold: "", red: "", green: "", yellow: "", cyan: "", dim: "" }
const log = (s) => console.log(`${C.cyan}[codeforge]${C.reset} ${s}`)
const ok = (s) => console.log(`${C.green}✓${C.reset} ${s}`)
const warn = (s) => console.warn(`${C.yellow}⚠${C.reset} ${s}`)
const err = (s) => console.error(`${C.red}✗${C.reset} ${s}`)
const hr = () => console.log(`${C.bold}────────────────────────────────────────────────${C.reset}`)

// ────────────────────────────────────────────────────────────────────
// 版本
// ────────────────────────────────────────────────────────────────────
function getVersion() {
  try {
    const pkg = JSON.parse(readFileSync(path.join(REPO_ROOT, "package.json"), "utf8"))
    return pkg.version ?? "0.0.0"
  } catch {
    return "0.0.0"
  }
}

// ────────────────────────────────────────────────────────────────────
// 安装来源检测：npm（npx / npm i -g）vs git clone
// ────────────────────────────────────────────────────────────────────
//
// 检测当前是否从 npm 上下文运行（npx / npm i -g 都会让用户调用路径落在 node_modules 下）。
//
// 注意：用 process.argv[1] 而非 __dirname / REPO_ROOT —— ESM import.meta.url 在 Windows
// junction 和 Linux/macOS symlink 下会被 Node.js 自动 resolve 到真实路径，丢失 node_modules
// 上下文；process.argv[1] 保留用户实际调用路径，不会被解析。
function isFromNpm() {
  const entry = process.argv[1] ?? ""
  if (entry.includes(`${path.sep}node_modules${path.sep}`)) return true
  // fallback：npm 包里没有 build-with-version.mjs（只有 dist/），检测它不存在即为 npm 场景
  const buildScript = path.join(REPO_ROOT, "scripts", "build-with-version.mjs")
  return !existsSync(buildScript)
}

// ────────────────────────────────────────────────────────────────────
// 参数解析（手解析，避免引 commander）
// ────────────────────────────────────────────────────────────────────
function parseArgs(argv) {
  const args = { _: [], flags: {} }
  for (const a of argv) {
    if (a.startsWith("--")) {
      const [k, ...rest] = a.slice(2).split("=")
      args.flags[k] = rest.length > 0 ? rest.join("=") : true
    } else {
      args._.push(a)
    }
  }
  return args
}

// ────────────────────────────────────────────────────────────────────
// opencode installer：薄壳，统一调 install.mjs（Node ESM 跨平台）
// ADR:unify-install-to-node-mjs / ADR:cli-deadcode-cleanup
// install.sh/.ps1 已合并进 install.mjs，installer 永远走 node。
// ────────────────────────────────────────────────────────────────────
function resolveInstallerScript() {
  const mjsScript = path.join(REPO_ROOT, "install.mjs")
  if (existsSync(mjsScript)) return { script: mjsScript }
  return null
}

function installOpencode({ scope, dryRun, extraArgs, quiet = false, verbose = false }) {
  const resolved = resolveInstallerScript()
  if (!resolved) {
    err(`installer 脚本不存在：${path.join(REPO_ROOT, "install.mjs")}`)
    return 2
  }
  const { script } = resolved
  const cmd = process.execPath
  const args = [script]
  if (scope === "global") args.push("--global")
  if (dryRun) args.push("--dry-run")
  if (verbose) args.push("--verbose")
  if (extraArgs) args.push(...extraArgs)
  if (!quiet) log(`opencode: node ${args.join(" ")}`)
  const r = spawnSync(cmd, args, { stdio: quiet ? "pipe" : "inherit", cwd: REPO_ROOT })
  if (quiet && r.status !== 0) {
    if (r.stderr) process.stderr.write(r.stderr)
    if (r.stdout) process.stderr.write(r.stdout)
  }
  return r.status ?? 1
}

function uninstallOpencode({ scope }) {
  const resolved = resolveInstallerScript()
  if (!resolved) {
    err(`installer 脚本不存在：${path.join(REPO_ROOT, "install.mjs")}`)
    return 2
  }
  const { script } = resolved
  const cmd = process.execPath
  const args = [script, "--uninstall"]
  if (scope === "global") args.push("--global")
  log(`opencode uninstall: node ${args.join(" ")}`)
  const r = spawnSync(cmd, args, { stdio: "inherit", cwd: REPO_ROOT })
  return r.status ?? 1
}

function detectOpencode() {
  const opencodeCmd = process.platform === "win32" ? "opencode.cmd" : "opencode"
  const r = spawnSync(opencodeCmd, ["--version"], { stdio: "pipe", encoding: "utf8" })
  if (r.status === 0) return { installed: true, version: (r.stdout ?? "").trim() }
  return { installed: false }
}

// ────────────────────────────────────────────────────────────────────
// 子命令：install
// ────────────────────────────────────────────────────────────────────
function cmdInstall(args) {
  const scope = "global"
  const dryRun = !!args.flags["dry-run"] || !!args.flags.dryRun
  const fromNpm = isFromNpm()
  // npm 场景下 dist/ 已经被 prepack 打过包随 tarball 发布，强制 --skip-build
  // （node_modules 里通常没有 dev 依赖，跑 npm run build 会失败）
  const autoSkipBuild = fromNpm
  const verbose = !!args.flags.verbose
  const extraArgs = []
  if (args.flags["skip-build"] || autoSkipBuild) extraArgs.push("--skip-build")

  // npm 场景：dist/index.js 必须已经被 prepack 打好；找不到就直接报错并提示
  if (fromNpm && !dryRun) {
    const distEntry = path.join(REPO_ROOT, "dist", "index.js")
    if (!existsSync(distEntry)) {
      err(`从 npm 安装但找不到 prebuilt bundle：${distEntry}`)
      err(`这通常是 package 发布问题：dist/ 没被 npm pack 进 tarball。`)
      err(`临时解决：从 GitHub clone 后跑 node install.mjs`)
      return 1
    }
  }

  const code = installOpencode({ scope, dryRun, extraArgs, verbose })
  if (code !== 0) {
    err(`opencode 安装失败 (exit=${code})`)
    return 1
  }
  return 0
}

// ────────────────────────────────────────────────────────────────────
// 子命令：uninstall
// ────────────────────────────────────────────────────────────────────
function cmdUninstall(args) {
  const scope = "global"
  uninstallOpencode({ scope })
  return 0
}

// ────────────────────────────────────────────────────────────────────
// 子命令：list（探测 opencode）
// ────────────────────────────────────────────────────────────────────
function cmdList() {
  log(`检测 opencode：`)
  hr()
  const d = detectOpencode()
  const present = d.installed ? `${C.green}✓${C.reset} ${d.version ?? ""}` : `${C.dim}— 未安装${C.reset}`
  console.log(`  ${C.green}ready${C.reset}  opencode  ${present}`)
  hr()
  if (!d.installed) {
    warn(`未检测到 opencode，请先安装：https://github.com/sst/opencode`)
  }
  return 0
}

// ────────────────────────────────────────────────────────────────────
// 子命令：upgrade —— 升级到 npm latest 并重新 install --global
// ────────────────────────────────────────────────────────────────────

async function cmdUpgrade(args) {
  const dryRun = !!args.flags["dry-run"] || !!args.flags.dryRun
  const currentVersion = getVersion()

  log(`检查版本...`)

  // 查询 npm registry 最新版本
  let latestVersion = null
  try {
    latestVersion = await new Promise((resolve) => {
      import("node:https").then((mod) => {
        const https = mod.default ?? mod  // node:https ESM 无 default export
        const options = {
          hostname: "registry.npmjs.org",
          path: "/@andyqiu%2Fcodeforge/latest",
          method: "GET",
          headers: { "User-Agent": "codeforge-cli" },
          timeout: 5000,
        }
        const req = https.get(options, (res) => {
          let data = ""
          res.on("data", (chunk) => { data += chunk })
          res.on("end", () => {
            try { resolve(JSON.parse(data).version ?? null) } catch { resolve(null) }
          })
        })
        req.on("timeout", () => { req.destroy(); resolve(null) })
        req.on("error", () => resolve(null))
      }).catch(() => resolve(null))
    })
  } catch {
    latestVersion = null
  }

  if (latestVersion === null) {
    warn(`版本检查失败，继续升级流程`)
  } else if (latestVersion === currentVersion) {
    ok(`当前已是最新版本 v${currentVersion}，无需升级`)
    return 0
  } else {
    log(`当前版本：${currentVersion} → 最新版本：${latestVersion}`)
  }

  const npmCmd = process.platform === "win32" ? "npm.cmd" : "npm"
  // 始终用 @latest 安装，避免 CDN 同步延迟导致的 ETARGET 错误
  // 精确版本号仅用于展示，不用于 npm install
  const installTarget = "@andyqiu/codeforge@latest"
  const npmArgs = ["install", "-g", installTarget, "--no-audit", "--no-fund"]

  if (dryRun) {
    const displayNew = latestVersion ?? "未知（版本查询失败）"
    ok(`[dry-run] 演示升级：${currentVersion} → ${displayNew}`)
    ok(`[dry-run] 实际执行时将自动重启生效提示`)
    return 0
  }

  const r = spawnSync(npmCmd, npmArgs, {
    stdio: "inherit",
    env: {
      ...process.env,
      npm_config_audit: "false",
      npm_config_fund: "false",
    },
  })

  if (r.status !== 0) {
    err(`npm install 失败 (exit=${r.status ?? 1})`)
    err(`提示：可手动跑 npm install -g ${installTarget}`)
    return 1
  }

  // postinstall 已自动跑 codeforge install --global，无需重复执行

  // 升级后读取新版本（npm install 成功后本地 package.json 已更新）
  const newVersion = latestVersion ?? getVersion()
  ok(`升级完成：${currentVersion} → ${newVersion}`)
  ok(`重启 opencode 后新版本生效`)
  return 0
}

// ────────────────────────────────────────────────────────────────────
// 子命令：doctor —— 转发到 codeforge-doctor.mjs（ADR:codeforge-doctor-command）
// 不依赖 dist/，直接 import install.mjs export，npm 安装场景也能跑。
// ────────────────────────────────────────────────────────────────────
function cmdDoctor(args) {
  const target = path.join(REPO_ROOT, "bin", "codeforge-doctor.mjs")
  if (!existsSync(target)) {
    err(`doctor 脚本不存在：${target}`)
    err(`请重装 codeforge：npm install -g @andyqiu/codeforge`)
    return 2
  }
  // 透传所有参数（--project / --help 等）
  const passArgs = args._[0] === "doctor" ? args._.slice(1) : args._
  const flagArgs = Object.entries(args.flags).map(([k, v]) => v === true ? `--${k}` : `--${k}=${v}`)
  const r = spawnSync(process.execPath, [target, ...passArgs, ...flagArgs], { stdio: "inherit" })
  return r.status ?? 1
}

// ────────────────────────────────────────────────────────────────────
// 子命令：runtime —— 转发到 codeforge-runtime-info.mjs
// ────────────────────────────────────────────────────────────────────
function cmdRuntime(args) {
  const sub = args._[0] ?? "where"
  if (sub !== "where") {
    err(`未知 runtime 子命令：${sub}（仅支持 where）`)
    return 2
  }
  const target = path.join(REPO_ROOT, "bin", "codeforge-runtime-info.mjs")
  if (!existsSync(target)) {
    err(`runtime-info 脚本不存在：${target}`)
    return 2
  }
  const passArgs = args._.slice(1) // where 之后的可选 path
  const r = spawnSync(process.execPath, [target, ...passArgs], { stdio: "inherit" })
  return r.status ?? 1
}

// ────────────────────────────────────────────────────────────────────
// 子命令：adr-init —— 把 ADR 体系下发到当前 git 项目 (ADR:adr-distribution-init)
// ────────────────────────────────────────────────────────────────────
//
// 实现走 dist/adr-init.js 这个**确定路径**（由 scripts/build-with-version.mjs 第二
// bun build entry 产出）。既适用 npm 包安装（pkgRoot/dist/adr-init.js），也适用本
// 仓库 dev 期（repoRoot/dist/adr-init.js）。没有 fallback —— 缺 dist 文件就明确报错
// 提示跑 npm run build，比 ts-node / 源码动态 import 简单可靠。
async function cmdAdrInit(args) {
  const cwd = process.cwd()
  const opts = {
    cwd,
    force: !!args.flags.force,
    dryRun: !!args.flags["dry-run"] || !!args.flags.dryRun,
    writePrepare: !!args.flags["write-prepare"] || !!args.flags.writePrepare,
    installPrePush: args.flags["no-pre-push"] ? false : true,
  }

  const adrInitPath = path.join(REPO_ROOT, "dist", "adr-init.js")
  if (!existsSync(adrInitPath)) {
    err(`找不到 ${adrInitPath}`)
    err(`如果是从源码运行：请先跑 npm run build`)
    err(`如果是 npm 安装：可能是发布缺文件，请重装或反馈给 @andyqiu/codeforge`)
    return 1
  }

  log(`CodeForge adr-init —— 下发 ADR 体系到 ${cwd}`)
  log(`  force          : ${opts.force}`)
  log(`  dry-run        : ${opts.dryRun}`)
  log(`  write-prepare  : ${opts.writePrepare}`)
  log(`  install pre-push: ${opts.installPrePush}`)
  hr()

  // ESM dynamic import 必须用 file:// URL，Win 路径才能正确解析
  let mod
  try {
    mod = await import(url.pathToFileURL(adrInitPath).href)
  } catch (e) {
    err(`加载 ${adrInitPath} 失败：${e?.message ?? e}`)
    return 1
  }
  if (typeof mod.runAdrInit !== "function") {
    err(`${adrInitPath} 缺少 runAdrInit 导出（bundle 可能损坏，请重建 dist/）`)
    return 1
  }

  let result
  try {
    result = await mod.runAdrInit(opts)
  } catch (e) {
    err(`adr-init 执行抛错：${e?.stack ?? e}`)
    return 1
  }

  if (result.wrote?.length) {
    ok(`已写入 ${result.wrote.length} 个文件：`)
    for (const f of result.wrote) console.log(`  + ${f}`)
  }
  if (result.skipped?.length) {
    warn(`已跳过 ${result.skipped.length} 个已存在文件（用 --force 覆盖）：`)
    for (const f of result.skipped) console.log(`  · ${f}`)
  }
  if (result.backedUp?.length) {
    ok(`已备份 ${result.backedUp.length} 个原文件：`)
    for (const f of result.backedUp) console.log(`  ↳ ${f}`)
  }
  for (const s of result.suggestions ?? []) log(s)
  for (const w of result.warnings ?? []) warn(w)
  if (opts.dryRun) log("dry-run 模式：以上未实际写盘")
  hr()
  return result.ok === false ? 1 : 0
}

// ────────────────────────────────────────────────────────────────────

// 子命令：help
// ────────────────────────────────────────────────────────────────────
function cmdHelp() {
  console.log(`${C.bold}codeforge${C.reset} — opencode 的零侵入扩展包安装入口

用法：
  codeforge install    [--dry-run] [--skip-build]
  codeforge uninstall
  codeforge list
  codeforge version
  codeforge upgrade|update    [--dry-run]   # 升级到 npm latest 并重新 install --global
  codeforge doctor     [--project]   # 诊断 CodeForge 安装健康状态（manifest/disk/source 三方比对）
  codeforge runtime where [<path>]   # 打印当前项目的全局运行时目录
  codeforge adr-init   [--force] [--dry-run] [--write-prepare] [--no-pre-push]
                                     # 把 ADR 校验体系（hooks + scripts + 模板）下发到当前 git 项目

安装：
  npm install -g @andyqiu/codeforge

参数：
  --dry-run              只打印操作，不真改
  --skip-build           跳过 npm run build（已有 dist/index.js 时增量装）

参数（adr-init 专用）：
  --force                覆盖已存在文件（覆盖前自动 .bak.<ts> 备份）
  --dry-run              只打印将要执行的写入计划，不实际写盘
  --write-prepare        合并 git config core.hooksPath 到 package.json scripts.prepare（写前 backup package.json；默认只建议不写）
  --no-pre-push          跳过 .githooks/pre-push 生成（只装 pre-commit）

CodeForge 是 opencode 1.14+ 的单 bundle plugin（持续跟主线，src/index.ts → dist/index.js），
通过往 opencode.json 写一行 plugin entry 来装载。
不支持 Cursor / Claude Code / Codex —— 它们的扩展机制不同，强行映射只会变成
半残的 markdown 拷贝，与 CodeForge 真实能力（17 个 hook + tool 注册）不符。

更多文档：https://github.com/andy-personal/code-forge`)
  return 0
}

// ────────────────────────────────────────────────────────────────────
// main —— async (ADR:adr-distribution-init: adr-init 需 dynamic import)
// ────────────────────────────────────────────────────────────────────
//
// 改成 async 后所有同步 case `return <number>` 自动被包成 Promise<number>，外层 .then
// 拿到数字调 process.exit 即可；现有 case 的 exit code 行为不变。
async function main() {
  const argv = process.argv.slice(2)
  if (argv.length === 0 || ["-h", "--help"].includes(argv[0])) {
    return cmdHelp()
  }
  const [sub, ...rest] = argv
  const args = parseArgs(rest)

  if (args.flags.client !== undefined) {
    warn(`--client 标志已废弃：CodeForge 只支持 opencode。忽略 --client=${args.flags.client}`)
  }

  switch (sub) {
    case "install":
      return cmdInstall(args)
    case "uninstall":
      return cmdUninstall(args)
    case "list":
      return cmdList()
    case "version":
    case "--version":
    case "-v":
      console.log(getVersion())
      return 0
    case "upgrade":
    case "update":
      return cmdUpgrade(args)
    case "doctor":
      return cmdDoctor(args)
    case "runtime":
      return cmdRuntime(args)
    case "adr-init":
      return cmdAdrInit(args)

    case "help":
      return cmdHelp()
    default:
      err(`未知子命令：${sub}`)
      cmdHelp()
      return 2
  }
}

main()
  .then((code) => process.exit(typeof code === "number" ? code : 0))
  .catch((e) => {
    err(`未捕获错误：${e?.stack ?? e}`)
    process.exit(1)
  })

